solution.Parallel.java:
import java.util.*;
import java.util.concurrent.*;

class Parallel {
    static <T> List<T> runAll(List<Callable<T>> tasks, Executor executor) throws Exception {
        List<CompletableFuture<T>> futures = new ArrayList<>();
        for (Callable<T> task : tasks) {
            CompletableFuture<T> f = new CompletableFuture<>();
            executor.execute(() -> {
                try {
                    f.complete(task.call());
                } catch (Throwable t) {
                    f.completeExceptionally(t);
                }
            });
            futures.add(f);
        }
        List<T> results = new ArrayList<>();
        for (CompletableFuture<T> f : futures) {
            try {
                results.add(f.get());
            } catch (ExecutionException e) {
                Throwable cause = e.getCause();
                if (cause instanceof Exception ex) throw ex;
                throw e;
            }
        }
        return results;
    }

    static long sumInChunks(int[] data, int chunks, Executor executor) {
        if (chunks < 1) throw new IllegalArgumentException("chunks must be at least 1");
        if (data.length == 0) return 0;
        int parts = Math.min(chunks, data.length);
        List<CompletableFuture<Long>> sums = new ArrayList<>();
        for (int c = 0; c < parts; c++) {
            int from = (int) ((long) c * data.length / parts), to = (int) ((long) (c + 1) * data.length / parts);
            sums.add(CompletableFuture.supplyAsync(() -> {
                long s = 0;
                for (int i = from; i < to; i++) s += data[i];
                return s;
            }, executor));
        }
        long total = 0;
        for (CompletableFuture<Long> f : sums) total += f.join();
        return total;
    }
}

solution.SafeCounter.java:
import java.util.concurrent.atomic.AtomicLong;

class SafeCounter {
    private final AtomicLong value = new AtomicLong();

    void increment() { value.incrementAndGet(); }
    void add(long n) { value.addAndGet(n); }
    long get() { return value.get(); }
    long getAndReset() { return value.getAndSet(0); }
}

unitTests:
Executor direct = Runnable::run;
List<String> log = new ArrayList<>();
Executor recording = task -> { log.add("task"); task.run(); };

test("running all tasks in order", () -> {
    List<Callable<Integer>> tasks = List.of(() -> 1, () -> 2 * 2, () -> 3 * 3);
    checkEq(Parallel.runAll(tasks, direct), List.of(1, 4, 9));
    log.clear();
    checkEq(Parallel.runAll(tasks, recording), List.of(1, 4, 9));
    checkEq(log.size(), 3);
    checkEq(Parallel.runAll(List.<Callable<String>>of(), direct), List.of());
});

test("the first failure is rethrown", () -> {
    List<Callable<Integer>> tasks = List.of(
        () -> 1,
        () -> { throw new IllegalStateException("second failed"); },
        () -> { throw new java.io.IOException("third failed"); });
    try {
        Parallel.runAll(tasks, direct);
        check(false, "should throw");
    } catch (IllegalStateException e) {
        checkEq(e.getMessage(), "second failed");
    }
});

test("summing in chunks", () -> {
    int[] data = IntStream.rangeClosed(1, 1000).toArray();
    log.clear();
    checkEq(Parallel.sumInChunks(data, 4, recording), 500500L);
    checkEq(log.size(), 4);
    checkEq(Parallel.sumInChunks(data, 1, direct), 500500L);
    checkEq(Parallel.sumInChunks(new int[] {5, 6}, 10, direct), 11L);
    checkEq(Parallel.sumInChunks(new int[0], 3, direct), 0L);
    int[] big = new int[1_000_003];
    Arrays.fill(big, 2_000_000_000);
    checkEq(Parallel.sumInChunks(big, 7, direct), 2_000_000_000L * 1_000_003);
    checkThrows(IllegalArgumentException.class, () -> Parallel.sumInChunks(data, 0, direct));
});

test("a safe counter", () -> {
    SafeCounter c = new SafeCounter();
    for (int i = 0; i < 1000; i++) c.increment();
    c.add(500);
    checkEq(c.get(), 1500L);
    checkEq(c.getAndReset(), 1500L);
    checkEq(c.get(), 0L);
});

